using System;
using System.Collections.Generic;
using System.Linq;
using FOC.Domain.Battle;
using FOC.Domain.Characters;
using FOC.Domain.Common;
using FOC.Domain.Economy;
using FOC.Domain.Military;
using FOC.Domain.Random;
using FOC.Domain.Soldiers;
using FOC.Domain.Time;

namespace FOC.Application.Save
{
    public static partial class CampaignSaveMapper
    {
        private static void AddBattleSaveData(FOC.Domain.Campaign.CampaignRuntimeState state,CampaignSaveData data)
        {
            foreach(var battle in state.Battles.Battles.OrderedBattles){var b=new BattleSaveData{BattleId=battle.Id.Value,StartedAt=battle.StartedAt.Ticks,Lifecycle=(int)battle.Lifecycle,Step=battle.Step,RngState=battle.RandomState.State,RngDrawCount=battle.RandomState.DrawCount,IsReconciled=battle.IsReconciled};foreach(var side in battle.OrderedSides){var s=new BattleSideSaveData{SideId=side.Id.Value,CommanderCharacterId=side.CommanderId.Value};foreach(var participant in side.OrderedParticipants){var p=new BattleParticipantSaveData{ArmyId=participant.ArmyId.Value,CommanderCharacterId=participant.CommanderId.Value};foreach(var supply in participant.OrderedSupply)p.Supply.Add(new ArmySupplySaveData{TradeGoodId=supply.Key.Value,Quantity=supply.Value});foreach(var unit in participant.OrderedUnits){var u=new BattleUnitSnapshotSaveData{ArmyId=unit.ArmyId.Value,UnitGroupId=unit.UnitGroupId.Value,CommanderCharacterId=unit.CommanderId.HasValue?unit.CommanderId.Value.Value:string.Empty,CampaignHeadcount=unit.CampaignHeadcount,Morale=(int)unit.Morale,Fatigue=(int)unit.Fatigue,Discipline=(int)unit.Discipline};foreach(var combatant in unit.OrderedCombatants)u.Combatants.Add(new BattleCombatantSaveData{SoldierId=combatant.SoldierId.Value,UnitGroupId=combatant.UnitGroupId.Value,TroopDefinitionId=combatant.TroopDefinitionId.Value,CombatRoleId=combatant.CombatRoleId.Value,IsMounted=combatant.IsMounted,EquipmentInstanceIds=combatant.OrderedEquipment.Select(x=>x.Value).ToList()});p.Units.Add(u);}s.Participants.Add(p);}b.Sides.Add(s);}foreach(var sector in battle.Sectors.OrderedSectors)b.Sectors.Add(new BattleSectorSaveData{SectorId=sector.Id.Value,Terrain=sector.OrderedTerrain.Select(x=>(int)x).ToList(),EligibleSideIds=sector.OrderedEligibleSides.Select(x=>x.Value).ToList(),AdjacentSectorIds=sector.OrderedAdjacent.Select(x=>x.Value).ToList()});foreach(var x in battle.OrderedDeployments)b.Deployments.Add(new BattleDeploymentSaveData{DeploymentGroupId=x.Id.Value,SideId=x.SideId.Value,ArmyId=x.ArmyId.Value,UnitGroupId=x.UnitGroupId.Value,SectorId=x.SectorId.Value,Formation=(int)x.Formation,IsReserve=x.IsReserve});foreach(var x in battle.OrderedOrders)b.Orders.Add(new BattleOrderSaveData{BattleOrderId=x.Id.Value,Sequence=x.Sequence,Kind=(int)x.Kind,SideId=x.SideId.Value,IssuerCharacterId=x.IssuerId.Value,DeploymentGroupId=x.GroupId.Value,TargetSectorId=x.TargetSector.HasValue?x.TargetSector.Value.Value:string.Empty,TargetGroupId=x.TargetGroup.HasValue?x.TargetGroup.Value.Value:string.Empty,Formation=x.Formation.HasValue?(int?)x.Formation.Value:null});foreach(var x in battle.OrderedEvents)b.Events.Add(new BattleEventSaveData{BattleEventId=x.EventId.Value,Sequence=x.Sequence,TargetSoldierId=x.Target.Value,Outcome=(int)x.Outcome});foreach(var x in battle.Ammunition.OrderedAllocations)b.Ammunition.Add(new BattleAmmoSaveData{SoldierId=x.SoldierId.Value,AmmoFamilyId=x.FamilyId.Value,Quantity=x.Quantity});if(battle.Result!=null)b.Result=ResultToSave(battle.Result);data.Battles.Add(b);}
        }
        private static BattleResultSaveData ResultToSave(BattleResult result){var r=new BattleResultSaveData{EndReason=(int)result.EndReason,CompletedAt=result.CompletedAt.Ticks,ElapsedSteps=result.ElapsedSteps,WinningSideId=result.WinningSide.HasValue?result.WinningSide.Value.Value:string.Empty,ParticipatingSideIds=result.OrderedParticipatingSides.Select(x=>x.Value).ToList()};foreach(var x in result.OrderedUnitOutcomes)r.Units.Add(new BattleUnitOutcomeSaveData{UnitGroupId=x.UnitGroupId.Value,AggregateLosses=x.AggregateLosses,Morale=(int)x.Morale,Fatigue=(int)x.Fatigue,Discipline=(int)x.Discipline});foreach(var x in result.OrderedSoldierOutcomes)r.Soldiers.Add(new BattleSoldierOutcomeSaveData{SoldierId=x.SoldierId.Value,Outcome=(int)x.Outcome});foreach(var x in result.OrderedCharacterOutcomes)r.Characters.Add(new BattleCharacterOutcomeSaveData{CharacterId=x.CharacterId.Value,Outcome=(int)x.Outcome,InjurySeverity=x.InjurySeverity.HasValue?(int?)x.InjurySeverity.Value:null,CaptorCharacterId=x.CaptorId.HasValue?x.CaptorId.Value.Value:string.Empty,CaptorArmyId=x.CaptorArmyId.HasValue?x.CaptorArmyId.Value.Value:string.Empty});foreach(var x in result.OrderedAmmunitionOutcomes)r.Ammunition.Add(new BattleAmmoOutcomeSaveData{SoldierId=x.SoldierId.Value,AmmoFamilyId=x.FamilyId.Value,RemainingQuantity=x.RemainingQuantity});return r;}

        private static BattleCampaignState RestoreBattles(CampaignSaveData data)
        {
            var registry=new BattleRegistry();foreach(var b in data.Battles){var graph=new BattleSectorGraph();foreach(var x in b.Sectors)graph.Add(new BattleSector(BattleSectorId.Create(x.SectorId),x.Terrain.Select(v=>(BattleTerrainTag)v),x.EligibleSideIds.Select(BattleSideId.Create)));foreach(var x in b.Sectors)foreach(var adjacent in x.AdjacentSectorIds){var other=BattleSectorId.Create(adjacent);var id=BattleSectorId.Create(x.SectorId);if(id.CompareTo(other)<0)graph.Connect(id,other);}var sides=new List<BattleSideState>();foreach(var s in b.Sides){var participants=new List<BattleParticipantSnapshot>();foreach(var p in s.Participants){var units=new List<BattleUnitSnapshot>();foreach(var u in p.Units){var combatants=u.Combatants.Select(c=>new BattleCombatantSnapshot(SoldierId.Create(c.SoldierId),UnitGroupId.Create(c.UnitGroupId),TroopDefinitionId.Create(c.TroopDefinitionId),CombatRoleId.Create(c.CombatRoleId),c.EquipmentInstanceIds.Select(EquipmentInstanceId.Create),c.IsMounted));units.Add(new BattleUnitSnapshot(ArmyId.Create(u.ArmyId),UnitGroupId.Create(u.UnitGroupId),string.IsNullOrEmpty(u.CommanderCharacterId)?(CharacterId?)null:CharacterId.Create(u.CommanderCharacterId),u.CampaignHeadcount,combatants,(MoraleAssessment)u.Morale,(FatigueAssessment)u.Fatigue,(DisciplineAssessment)u.Discipline));}participants.Add(new BattleParticipantSnapshot(ArmyId.Create(p.ArmyId),CharacterId.Create(p.CommanderCharacterId),units,p.Supply.Select(x=>new KeyValuePair<TradeGoodId,long>(TradeGoodId.Create(x.TradeGoodId),x.Quantity))));}sides.Add(new BattleSideState(BattleSideId.Create(s.SideId),CharacterId.Create(s.CommanderCharacterId),participants));}var ammunition=new BattleAmmunitionState();foreach(var x in b.Ammunition)ammunition.Add(new BattleAmmoAllocation(SoldierId.Create(x.SoldierId),AmmoFamilyId.Create(x.AmmoFamilyId),x.Quantity));var battle=new BattleState(BattleId.Create(b.BattleId),new WorldTimestamp(b.StartedAt),new RandomState(b.RngState,b.RngDrawCount),sides,graph,ammunition,(BattleLifecycle)b.Lifecycle,b.Step,b.IsReconciled);foreach(var x in b.Deployments)battle.RestoreDeployment(new BattleDeployment(DeploymentGroupId.Create(x.DeploymentGroupId),BattleSideId.Create(x.SideId),ArmyId.Create(x.ArmyId),UnitGroupId.Create(x.UnitGroupId),BattleSectorId.Create(x.SectorId),(BattleFormation)x.Formation,x.IsReserve));foreach(var x in b.Orders)battle.RestoreOrder(new BattleOrder(BattleOrderId.Create(x.BattleOrderId),x.Sequence,(BattleOrderKind)x.Kind,BattleSideId.Create(x.SideId),CharacterId.Create(x.IssuerCharacterId),DeploymentGroupId.Create(x.DeploymentGroupId),string.IsNullOrEmpty(x.TargetSectorId)?(BattleSectorId?)null:BattleSectorId.Create(x.TargetSectorId),string.IsNullOrEmpty(x.TargetGroupId)?(DeploymentGroupId?)null:DeploymentGroupId.Create(x.TargetGroupId),x.Formation.HasValue?(BattleFormation?)x.Formation.Value:null));foreach(var x in b.Events)battle.RestoreEvent(new BattleCombatOutcome(BattleEventId.Create(x.BattleEventId),x.Sequence,SoldierId.Create(x.TargetSoldierId),(BattleCasualtyOutcome)x.Outcome));if(b.Result!=null)battle.RestoreResult(ResultFromSave(b.BattleId,b.Result));registry.Add(battle);}return new BattleCampaignState(registry);
        }
        private static BattleResult ResultFromSave(string battleId,BattleResultSaveData r)=>new BattleResult(BattleId.Create(battleId),(BattleEndReason)r.EndReason,new WorldTimestamp(r.CompletedAt),r.ElapsedSteps,string.IsNullOrEmpty(r.WinningSideId)?(BattleSideId?)null:BattleSideId.Create(r.WinningSideId),r.Units.Select(x=>new BattleUnitOutcome(UnitGroupId.Create(x.UnitGroupId),x.AggregateLosses,(MoraleAssessment)x.Morale,(FatigueAssessment)x.Fatigue,(DisciplineAssessment)x.Discipline)),r.Soldiers.Select(x=>new BattleSoldierOutcome(SoldierId.Create(x.SoldierId),(BattleCasualtyOutcome)x.Outcome)),r.Characters.Select(x=>new BattleCharacterOutcome(CharacterId.Create(x.CharacterId),(BattleCasualtyOutcome)x.Outcome,x.InjurySeverity.HasValue?(CharacterInjurySeverity?)x.InjurySeverity.Value:null,string.IsNullOrEmpty(x.CaptorCharacterId)?(CharacterId?)null:CharacterId.Create(x.CaptorCharacterId),string.IsNullOrEmpty(x.CaptorArmyId)?(ArmyId?)null:ArmyId.Create(x.CaptorArmyId))),r.ParticipatingSideIds.Select(BattleSideId.Create),r.Ammunition.Select(x=>new BattleAmmoOutcome(SoldierId.Create(x.SoldierId),AmmoFamilyId.Create(x.AmmoFamilyId),x.RemainingQuantity)));
    }
}
